const char* getNamedResource (const char* resourceNameUTF8, int& numBytes);
const char* getNamedResource (const char* resourceNameUTF8, int& numBytes)
{
    unsigned int hash = 0;

    if (resourceNameUTF8 != nullptr)
        while (*resourceNameUTF8 != 0)
            hash = 31 * hash + (unsigned int) *resourceNameUTF8++;

    switch (hash)
    {
        case 0x6fac80d3:  numBytes = 59871; return saw_png;
        case 0x1e06b177:  numBytes = 27992; return sine_png;
        case 0x7c9d6407:  numBytes = 22597; return square_png;
        case 0x147f321e:  numBytes = 26106; return square1_png;
        case 0x148d499f:  numBytes = 34642; return square2_png;
        case 0xd3cea772:  numBytes = 48007; return triangle_png;
        case 0x626f049c:  numBytes = 152208; return RobotoItalic_ttf;
        case 0x93fe9a1e:  numBytes = 146004; return RobotoRegular_ttf;
        default: break;
    }

    numBytes = 0;
    return nullptr;
}

